/*等相遇-烤冷面大王*/

/*禁止商用/二传*/


/*大部分都是在变量里面🌷🌷🌷部分改*/

/* ====== 全局字体与变量 ====== */
@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fbold.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A700%3Bfont-display%3Aswap%3B%7D%40font-face%7Bfont-family%3A%22ZSFT-bo%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2Fbo%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
  font-family: "KingHwaOldSong";
  font-weight: normal;
}

/* 英文专用 ZSFT-bo */
#send_textarea,
.message-content,
.bubble-content,
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  font-family: "ZSFT-bo", "KingHwaOldSong", sans-serif !important;
}


:root {
  /*🌷🌷🌷自定义区*/
  --拍立得图片: url('https://i.postimg.cc/c1tJ6pJP/IMG-1364.jpg');

  --圆形图片: url('https://i.postimg.cc/v8vG1Gsf/IMG-1367.jpg');

  --面板背景: url('https://i.postimg.cc/RhhPgCJG/IMG-5180.jpg');

  --输入框文字: "世界は止まることなく回り続け、私たちが出会うまで。✩°";

  --思维链外显文字: "🖇️愛を隱しきれせん✧*";

  --欢迎页助手头像: url('https://i.postimg.cc/v8vG1Gsf/IMG-1367.jpg');

  --欢迎页助手名称:"user";

  --欢迎页助手信息: "世界は止まることなく回り続け、私たちが出会うまで。✩°";

  /* ❌不用动，Logo 图标变量 */
  --logo1: url('https://i.postimg.cc/VN2WB9BM/IMG-5171.png');
  --logo2: url('https://i.postimg.cc/7hn1kFvM/IMG-5170.png');

  /* ====== 🌷🌷🌷大小、位置大部分改这里⬇️====== */

  --头像框上下位置: 57%;
  --头像框左右位置: 50%;
  --头像框宽: 410px;
  --头像框高: 410px;


  --头像宽: 250px;
  --头像高: 250px;
  --头像左右偏移: -25px;
  --头像显示左右: 50%;/*这个没啥用*/
  --头像显示上下: 10%;


  --头像与下方元素间距: 13px;/*三元素上下*/
  --三元素之间间距: 10px;
  --头像上间距: 100px;
  --头像下间距: 20px;

  --圆位置上: 220px;
  --圆位置左: 330px;
  --圆大小宽: 44px;
  --圆大小高: 44px;

  --拍立得位置上: 313px;
  --拍立得位置左: 211px;
  --拍立得大小宽: 110px;
  --拍立得大小高: 110px;
  --拍立得旋转角度: -29deg;

  --角色名字字体大小: 18px;
  --角色名字左右: 220px;
  --角色名字上下: -35px;

  --最后一条消息名字上下: -40px;

  --助手消息圆位置上: 230px;
  --助手消息圆位置左: 330px;
  --助手消息拍立得位置上: 324px;
  --助手消息拍立得位置左: 212px;

  --展开面板下移距离: 15px;
}

/*===顶栏部分===*/
#top-bar {
    position: fixed !important;
    top: 0;
    left: 0;
    width: 500px;
    height: 40px;
    background: #fff !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    pointer-events: none;
}

#top-bar::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 120%;
    background: #fff !important;
    z-index: 1;
    pointer-events: auto;
}

#top-bar::after {
    content: "";
    position: fixed;
    top: -65px;
    right: 80px;
    width: 260px;
    height: 200px;
    background: transparent !important;
    z-index: 2;
    pointer-events: none;
}

/*by墨千尾老师，图标替换*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden;
}

#top-settings-holder .drawer { flex: 1; }

#top-settings-holder .drawer-icon {
    display: block;
    margin-top: 15px;
    background-color: transparent;
    border-radius: 0px !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 20px;
    height: 20px;
    opacity: 1 !important;
}

.drawer-icon.fa-fw:hover { transform: translateY(-1.5px); }

/* --- 顶栏九个图标替换（加补丁） --- */
.drawer-icon.fa-sliders { background-image: var(--logo1); }
.drawer-icon.fa-plug { background-image: var(--logo1); }
.drawer-icon.fa-font { background-image: var(--logo1); }
.drawer-icon.fa-book-atlas { background-image: var(--logo1); }
.drawer-icon.fa-user { background-image: var(--logo1); }
.drawer-icon.fa-image { background-image: var(--logo1); }
.drawer-icon.fa-cubes { background-image: var(--logo1); }
.drawer-icon.fa-bars-progress { background-image: var(--logo1); }
.drawer-icon.fa-face-smile { background-image: var(--logo1); }
.drawer-icon.fa-address-card { background-image: var(--logo1); }

#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--logo1) !important;
    transform: scale(1); 
}

#backgrounds-drawer-toggle .drawer-icon{
    background-image: var(--logo1) !important;
    transform: scale(1); 
}

#user-settings-button .drawer-icon {
    background-image: var(--logo1) !important;
    transform: scale(1); 
}

/* 展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: var(--logo2) !important; 
    transform: scale(1.2); 
}

/*底栏*/
#send_form {
    margin-bottom: 2px;
    width: 100%;
    background: #fff !important;
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    border-radius: 8px !important;
    border: 1px solid transparent !important;
    padding: 8px;
}

/* 输入框 */
#send_textarea {
    border-radius: 6px !important;
    clip-path: none !important;
    background-color: #fff !important;
    border-color: transparent !important;
}

/* --- 底部按键图标替换 --- */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
    display: none !important;
}

#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
    width: 20px !important;
    height: 30px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border-radius: 0px !important;
    opacity: 1 !important;
}

#options_button,
#extensionsMenuButton {
    background-image: var(--logo1) !important;
}

#send_but {
    background-image: var(--logo2) !important;
}

#quick-reply-rocket-button {
    background-image: var(--logo1) !important;
}

/* 输入框样式 */
#send_textarea {
    border-radius: 6px !important;
    clip-path: none !important;
    background-color:#f1f1f1!important; /* 纯白背景 */
    border-color: transparent !important;
}

/* ===== by墨千尾老师，输入框提示文字自定义 ===== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--输入框文字);
    color: #4A4A4A !important;
    position: absolute; 
    left: 55%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.4em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/*面板背景*/
.drawer-content {
    background: linear-gradient(rgba(255,255,255,0.5), rgba(255,255,255,0.5)), var(--面板背景) center/cover fixed no-repeat;
}

/*头像框*/
/* 来自hy老师，限制只在聊天消息区域内的头像显示头像框 */
#chat .mes .avatar {
    position: relative;
    border-radius: 50%;
    overflow: visible; /* 改为visible允许内容溢出 */
    flex-shrink: 0;
    z-index: 1;
}

#chat .mes .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 0%;/* 头像圆角，方角改为0 */
    position: relative;
    z-index: 1;
}

/* 添加头像框效果 - 只在聊天消息区域显示 */
#chat .mes .avatar::after {
    content: '';
    position: absolute;
    top: var(--头像框上下位置);
    left: var(--头像框左右位置);
    transform: translate(-50%, -50%);
    width: var(--头像框宽);
    height: var(--头像框高);
    background-image: url('https://i.postimg.cc/HxpNccXB/IMG-5185.png'); /* 替换为您的头像框图片URL */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 6; /* 确保头像框在头像之上 */
    pointer-events: none;
}

/*来自眠N老师*/
.mes {
    display: flex;
    flex-direction: column;
    align-items: center;
}
.mes .mesAvatarWrapper {
    display: flex;
    flex-wrap: wrap;
     justify-content: flex-start;
    gap: var(--头像与下方元素间距) var(--三元素之间间距);
    padding: var(--头像上间距) 0px var(--头像下间距);
}

/* 强制头像占据一整行，将其下方的元素推到下一行 */
.mes .mesAvatarWrapper .avatar {
    flex-basis: 100%;
    display: flex;
    justify-content: center;
}

.mesIDDisplay, .mes_timer, .tokenCounterDisplay {
    display: inline-block !important;
    font-size: 0.5em;
    transform:scale(0.8);
    color: #000;
    margin-top: 55px !important;
    z-index: 111;
}
/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
    display: none;
}

.last_mes .mesAvatarWrapper {
    padding-bottom: 25px; /* 最后一条消息头像区域与下方间距，保持与前面一致 */
}

/*----头像----*/
#chat .mes .avatar {
    position: relative;
    width: var(--头像宽);
    height: var(--头像高);
    border-radius: 50%;
    overflow: visible;
    flex-shrink: 0;
    z-index: 1;
}

#chat .mes .avatar img {
  position: relative !important;
  left: var(--头像左右偏移) !important;
  width: var(--头像宽) !important;
  height: var(--头像高) !important;
  object-fit: cover !important;
  object-position: var(--头像显示左右) var(--头像显示上下) !important;
}


/* 文本框与下一个头像框隔开 */
.mes {
    margin-bottom: 6em !important; 
    clear: both !important; 
}

/*文字铺满by墨千尾老师*/
.mes .mes_text {
    width: 100%;
    padding: 0px 5px 0px 0px;
    margin: 0px 0px 30px 0px;
}

/*——思维链——*/
.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;
    --bottom-padding: 1rem;
    --left-padding: 0.1rem;
    --right-padding: 0.1rem;
    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0;
    backdrop-filter: none !important; 
    -webkit-backdrop-filter: none !important; 
    padding: 0 !important;
    margin-bottom: 0 !important;
    color: var(--reasoning-text) !important;
    font-size: 1em !important;
    display: inline-flex !important;
    align-items: center !important;
    transition: none !important; 
}
/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}
/*来自N老师*/
.mes_reasoning_header_title::before {
    content: var(--思维链外显文字);
    font-size: 15px;
    color: #4A4A4A !important; 

}
.mes_reasoning_header_title {
    font-size: 0;
}

/*===自定义图片区===*/
/* 小圆图 */
.mes::before {
  content: '';
  position: absolute;
  z-index: 7;
  pointer-events: none;
  top: var(--圆位置上);
  left: var(--圆位置左);
  width: var(--圆大小宽);
  height: var(--圆大小高);
  border-radius: 50%;
  background-image: var(--圆形图片);
  background-size: cover;
  background-position: center;
}

/* 拍立得 */
.mes::after {
  content: '';
  position: absolute;
  z-index: 6;
  pointer-events: none;
  top: var(--拍立得位置上);
  left: var(--拍立得位置左);
  width: var(--拍立得大小宽);
  height: var(--拍立得大小高);
  transform: rotate(var(--拍立得旋转角度));
  transform-origin: left top;
  background-image: var(--拍立得图片);
  background-size: cover;
  background-position: center;
}

/* 🌷角色名字 */
.name_text {
  position: absolute !important;
  width: 100% !important;
  display: block !important;
  font-size: var(--角色名字字体大小) !important;
  text-align: left !important;
  margin-left: var(--角色名字左右) !important;
  margin-top: var(--角色名字上下) !important;
  z-index: 999 !important;
}

/* 🌷最后一条消息的名字 */
.last_mes .name_text {
  margin-left: var(--角色名字左右) !important;
  margin-top: var(--最后一条消息名字上下) !important;
  font-size: var(--角色名字字体大小) !important;
}

/*——图标统一替换 ——*/
/* 小铅笔 */
.fa-pencil-alt::before, .fa-pencil::before {
    display: none !important;
}
.fa-pencil-alt, .fa-pencil {
    background: var(--logo2) no-repeat center/contain !important;
    width: 20px !important;
    height: 20px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
    filter: grayscale(100%) contrast(120%) !important;
}

/* 三个点 */
.fa-ellipsis-h::before, .fa-ellipsis::before {
    display: none !important;
}
.fa-ellipsis-h, .fa-ellipsis {
    background: var(--logo1) no-repeat center/contain !important;
    width: 25px !important;
    height: 25px !important;
    display: inline-block;
    vertical-align: middle;
    opacity: 1 !important;
    transition: opacity 0.3s ease !important;
    filter: grayscale(100%) contrast(120%) !important;
}

.fa-pencil-alt:hover, 
.fa-pencil:hover, 
.fa-ellipsis-h:hover, 
.fa-ellipsis:hover {
    opacity: 0.7 !important;
}

/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 25px !important;
    height: 25px !important;
    background: var(--logo2) center/contain no-repeat !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

/* 火狐兼容 */
input[type="range"]::-moz-range-thumb {
    appearance: none;
    width: 25px !important;
    height: 25px !important;
    background: var(--logo2) center/contain no-repeat !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
}

/*预设编辑*/
.neo-range-slider {
    height: 3px !important;
    background: #ccc !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    z-index: 1;
    margin-bottom: 0px !important;
    border-radius: 0px !important;
}

.prompt-manager-edit-action::before {
    display: none !important;
}
.prompt-manager-edit-action {
    background: var(--logo1) no-repeat center/20px 20px !important;
    width: 25px !important;
    height: 25px !important;
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
}

/*编辑按钮位置*/
.mes_buttons {
    position: relative;
    top: 0px;
    left: -10px;
}

/*---文字样式 ---*/
.mes {
    color: #000 !important;
}

/* 引用文本 */
.mes q {
    background: #f1f1f1 !important;
    color: #000 !important;
    border: 1px solid #ccc !important;
    padding: 5px 10px !important;
    font-style: normal !important;
    border-radius: 4px !important;
    box-shadow: none !important;
    display: inline-block !important;
}

/* 斜体文本 */
.mes i,
.mes em {
    color: #666 !important;
    text-decoration: underline !important;
}

/* 下划线文本 */
.mes u {
    text-decoration: none !important;
    color: #000 !important;
    font-weight: bold !important;
    padding: 3px 6px !important;
    border-radius: 4px !important;
    background: #e5e5e5 !important;
    border-bottom: none !important;
}

/*===来自12老师，收藏区左右滑动===*/
/* 收藏角色边框  */
.character_select.is_fav .avatar {
    outline: 2px solid #999 !important;
    box-shadow: 0 0 6px #999, 0 0 12px #666, 0 0 18px #555 !important;
}

/* 收藏角色名字  */
.character_select.is_fav .ch_name {
    color: #222 !important;
    text-shadow: 0 0 6px #999, 0 0 12px #666, 0 0 24px #555 !important;
}

/*——切页——*/
.swipe_left::before, .swipe_right::before { content: '' !important; }
.swipe_left:hover, .swipe_right:hover { transform: scale(1.1); }
.swipes-counter { 
    color: #333; 
    opacity: 1 !important; 
    transform: translateY(50px) !important;
}

.swipe_right, .swipe_left {
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.2s ease;
    width: 20px;
    height: 30px;
    transform: translateY(50px) !important;
    filter: grayscale(100%) contrast(150%);
}

.swipe_right { background-image: var(--logo1); }
.swipe_left { background-image: var(--logo2); }

/* --- 折叠面板按键  --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 20px !important; 
    height: 20px !important; 
    background: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer;
    filter: none !important; 
    opacity: 1 !important; 
    color: #333 !important; 
    border: none !important; 
    box-shadow: none !important; 
}

.inline-drawer-icon::before {
    content: "" !important;
    display: block !important;
    background-image: var(--logo1) !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    width: 30px !important;
    height: 39px !important;
    color: transparent !important;
    filter: grayscale(100%) contrast(130%) !important;
    opacity: 1 !important; 
    text-shadow: none !important; 
}

.inline-drawer-icon:hover::before {
    transform: scale(1.2) !important;
}

/*图标去灰 */
#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop {
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#mes_stop i::before {
    opacity: 1 !important;
    filter: grayscale(100%) contrast(120%) !important;
    -webkit-filter: grayscale(100%) contrast(120%) !important;
}

/*提示词管理byserein老师 */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #000 !important;
    background: #f5f5f5 !important;
    background-size: 100%;
    border-radius: 1px 1px 12px 12px;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    border-radius: 15px !important;
    padding: 5px !important;
}
.completion_prompt_manager_prompt .fa-asterisk,
.completion_prompt_manager_prompt .fa-square-poll-horizontal,
.completion_prompt_manager_prompt .fa-syringe,
.completion_prompt_manager_prompt .fa-thumb-tack,
.fa-xs.fa-solid.fa-robot {
    color: #333 !important;
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #666 !important;
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager .completion_prompt_manager_header div,
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: #333 !important;
}
.inline-drawer-header .inline-drawer-icon {
